(function(g){const cabinets=[{id:'c1',name:'图书馆 · 梧桐书柜',place:'图书馆南门右侧 · A01',distance:'约 180m',hours:'08:00—22:00',capacity:24,x:32,y:44,open:true},{id:'c2',name:'生活区 · 微光书柜',place:'第二食堂旁 · B02',distance:'约 450m',hours:'全天开放',capacity:18,x:66,y:24,open:true},{id:'c3',name:'创意园 · 河岸书柜',place:'创意园咖啡店外 · C03',distance:'约 820m',hours:'维护中，暂不可借取',capacity:12,x:63,y:70,open:false}];const books=[{id:'b1',title:'小王子',author:'圣埃克苏佩里',category:'文学',condition:'九成新',cabinet:'c1',coins:24,price:9,color:'#ba744e',tag:'关于爱与成长'}, {id:'b2',title:'月亮与六便士',author:'毛姆',category:'文学',condition:'八五新',cabinet:'c1',coins:30,price:12,color:'#56725d',tag:'理想与日常之间'},{id:'b3',title:'人类简史',author:'尤瓦尔·赫拉利',category:'社科',condition:'九成新',cabinet:'c2',coins:42,price:18,color:'#e6d8b9',text:'#775f46',tag:'从一个问题开始'},{id:'b4',title:'解忧杂货店',author:'东野圭吾',category:'悬疑',condition:'九成新',cabinet:'c1',coins:32,price:12,color:'#5c7690',tag:'写给生活的回信'},{id:'b5',title:'设计心理学',author:'唐纳德·诺曼',category:'成长',condition:'八五新',cabinet:'c2',coins:38,price:15,color:'#bb6648',tag:'重新观察身边事物'},{id:'b6',title:'瓦尔登湖',author:'亨利·戴维·梭罗',category:'文学',condition:'九成新',cabinet:'c3',coins:26,price:10,color:'#88936e',tag:'慢下来的一种方式'}];const boxes=[{id:'x1',name:'悬疑之夜',desc:'翻开下一页之前，答案都还未知。',pool:['解忧杂货店','东方快车谋杀案','福尔摩斯探案集'],coins:60,color:'#576b77',tint:'#e6ecee'},{id:'x2',name:'给生活留白',desc:'在文字里，找到属于自己的慢节奏。',pool:['瓦尔登湖','小王子','浮生六记'],coins:50,color:'#9d9b71',tint:'#eeeedf'},{id:'x3',name:'灵感补给站',desc:'换一种视角，发现日常里的新可能。',pool:['设计心理学','艺术的故事','如何阅读一本书'],coins:70,color:'#ba7c50',tint:'#f3e9dc'}];const groups=[{id:'g1',name:'文学慢读俱乐部',members:128,tag:'文学 · 每周共读',desc:'这个星期，一起聊聊《小王子》里的大人。',icon:'文'},{id:'g2',name:'悬疑不剧透小组',members:86,tag:'悬疑 · 线索交换',desc:'交换阅读感受，把谜底留给下一位读者。',icon:'谜'},{id:'g3',name:'校园成长书桌',members:215,tag:'成长 · 学习分享',desc:'从一本书、一个新习惯开始。',icon:'知'}];const seed={version:1,balance:120,ledger:[{id:'welcome',text:'新旅人体验书币',amount:120,time:'演示初始奖励'}],books:structuredClone(books),orders:[],deposits:[],groups:['g1'],messages:{g1:[{name:'小禾',text:'欢迎新书友！这周你读到哪一本书了？'}],g2:[{name:'阿远',text:'分享可以很热闹，剧透请先留白。'}],g3:[{name:'木木',text:'今天也给自己留二十分钟阅读吧。'}]}};function id(){return 'r'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}function assert(v,m){if(!v)throw Error(m)}function change(s,text,amount){assert(s.balance+amount>=0,'书币不足，先投递旧书赚书币吧');s.balance+=amount;s.ledger.unshift({id:id(),text,amount,time:new Date().toLocaleString('zh-CN')})}function available(s,b){return !s.orders.some(o=>o.bookId===b.id&&['borrowed','bought'].includes(o.status))}function checkout(s,bookId,type){assert(['borrow','buy'].includes(type),'操作无效');const b=s.books.find(b=>b.id===bookId);assert(b,'找不到这本书');assert(cabinets.find(c=>c.id===b.cabinet)?.open,'该书柜正在维护');assert(available(s,b),'这本书已被借走或购买');if(type==='borrow')assert(s.orders.filter(o=>o.status==='borrowed').length<3,'最多同时借阅 3 本，请先归还');const cost=type==='borrow'?10:b.coins;change(s,(type==='borrow'?'借阅押币 · ':'购书兑换 · ')+b.title,-cost);const due=new Date();due.setDate(due.getDate()+14);const order={id:id(),bookId:b.id,title:b.title,cabinet:b.cabinet,status:type==='borrow'?'borrowed':'bought',deposit:type==='borrow'?10:0,due:due.toISOString().slice(0,10),code:String(Math.floor(100000+Math.random()*900000)),time:new Date().toISOString()};s.orders.unshift(order);return order}function returnBook(s,orderId){const o=s.orders.find(o=>o.id===orderId);assert(o?.status==='borrowed','这本书已归还或不可归还');const days=Math.max(0,Math.ceil((new Date().setHours(0,0,0,0)-new Date(o.due+'T23:59:59').getTime())/86400000));const fee=Math.min(o.deposit,days);change(s,'归还退押币 · '+o.title,o.deposit-fee);o.status='returned';o.fee=fee;return o}function estimate(condition){return {'全新':35,'九成新':25,'八五新':15}[condition]||0}function deposit(s,data){assert(data.title?.trim()&&data.author?.trim(),'请填写书名与作者');assert(estimate(data.condition)>0,'暂不接收此品相');const c=cabinets.find(c=>c.id===data.cabinet);assert(c?.open,'请选择营业中的书柜');assert(s.deposits.filter(d=>d.cabinet===c.id&&d.status==='pending').length<c.capacity,'该书柜投递空间已满');const d={...data,title:data.title.trim(),author:data.author.trim(),id:id(),reward:estimate(data.condition),status:'pending',time:new Date().toISOString()};s.deposits.unshift(d);return d}function review(s,depositId,pass){const d=s.deposits.find(d=>d.id===depositId);assert(d?.status==='pending','该投递已审核');if(pass){change(s,'回收通过 · '+d.title,d.reward);d.status='approved';s.books.push({id:id(),title:d.title,author:d.author,category:d.category,condition:d.condition,cabinet:d.cabinet,coins:Math.round(d.reward*1.4),price:Math.round(d.reward*.4),color:'#718368',tag:'来自书友的新旅程'})}else d.status='rejected';return d}function redeem(s,boxId,random=Math.random){const x=boxes.find(x=>x.id===boxId);assert(x,'盲盒不存在');change(s,'盲盒兑换 · '+x.name,-x.coins);const o={id:id(),title:x.pool[Math.min(x.pool.length-1,Math.floor(random()*x.pool.length))],theme:x.name,status:'box',cabinet:'c1',code:String(Math.floor(100000+Math.random()*900000)),time:new Date().toISOString()};s.orders.unshift(o);return o}function validate(s){assert(s?.version===1&&Number.isInteger(s.balance)&&s.balance>=0,'书币数据无效');for(const k of ['ledger','books','orders','deposits','groups'])assert(Array.isArray(s[k])&&s[k].length<5000,'备份结构无效');assert(s.messages&&typeof s.messages==='object','消息数据无效');assert(s.ledger.every(l=>Number.isInteger(l.amount)&&typeof l.text==='string'),'流水无效');assert(s.ledger.reduce((n,l)=>n+l.amount,0)===s.balance,'余额与流水不一致');assert(s.books.every(b=>typeof b.title==='string'&&typeof b.id==='string'&&Number.isInteger(b.coins)&&b.coins>0&&cabinets.some(c=>c.id===b.cabinet)),'书籍数据无效');assert(s.orders.every(o=>['borrowed','bought','returned','box'].includes(o.status)&&typeof o.id==='string'&&typeof o.title==='string'),'订单无效');assert(s.deposits.every(d=>['pending','approved','rejected'].includes(d.status)&&typeof d.title==='string'&&estimate(d.condition)>0),'投递记录无效');return s}g.BookMap={cabinets,boxes,groups,seed,available,checkout,returnBook,estimate,deposit,review,redeem,validate,id};if(typeof module!=='undefined')module.exports=g.BookMap})(globalThis);
